using EnterpriseDocumentIntelligence.SearchService.Application;using EnterpriseDocumentIntelligence.SearchService.Domain; namespace EnterpriseDocumentIntelligence.SearchService.Infrastructure; public sealed class EmptySearchProvider:ISearchProvider{public Task<IReadOnlyList<SearchHit>> SearchAsync(SearchQuery query,CancellationToken ct=default)=>Task.FromResult((IReadOnlyList<SearchHit>)Array.Empty<SearchHit>());} public static class SearchServiceInfrastructure{public static IServiceCollection AddSearchApplication(this IServiceCollection services){services.AddSingleton<ISearchProvider,EmptySearchProvider>();services.AddScoped<SearchApplicationService>();return services;}}